import * as THREE from 'three';import {FISH_GRILL} from './cooking-layout.js';import {createToyKit} from '../world/toy-kit.js';
export function buildFishGrill(root){const g=new THREE.Group();g.name='camp.fish-grill';const f=FISH_GRILL.fixture;g.position.set(f.x,0,f.z);g.rotation.y=f.yaw;root.add(g);const {mat}=createToyKit(g),body=new THREE.Mesh(new THREE.BoxGeometry(1.3,.18,.84),mat('#546970'));body.position.y=.76;body.castShadow=body.receiveShadow=true;g.add(body);const top=new THREE.Mesh(new THREE.PlaneGeometry(1.17,.70),mat('#263a41'));top.rotation.x=-Math.PI/2;top.position.y=.854;g.add(top);for(const x of [-.48,.48])for(const z of [-.28,.28]){const leg=new THREE.Mesh(new THREE.CylinderGeometry(.035,.045,.70,6),mat('#728c83'));leg.position.set(x,.375,z);leg.castShadow=true;g.add(leg);}const points=[];for(let i=0;i<7;i++)points.push(new THREE.Vector3(-.51+i*.17,.86,-.31),new THREE.Vector3(-.51+i*.17,.86,.31));const bars=new THREE.LineSegments(new THREE.BufferGeometry().setFromPoints(points),new THREE.LineBasicMaterial({color:'#c5c4ac'}));g.add(bars);return g;}
